mapper.select:
SELECT r.id, r.system_code as systemCode, s.name as systemName, r.task_name as taskName, r.task_status as taskStatus, r.start_time as startTime, r.end_time as endTime, r.data_date as dataDate FROM t_task_realtime_monitor r LEFT JOIN sys_system s ON r.system_code = s.client_id WHERE r.start_time >= CURRENT_DATE
AND r.system_code = #{systemId}
ORDER BY r.start_time DESC
